fn json_string(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c <= '\u{1f}' => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn values(ids: &[usize], cells: &[String]) -> Option<Vec<String>> {
    ids.iter().map(|&i| cells.get(i).cloned()).collect()
}

fn pack(items: &[String]) -> String {
    format!("[{}]", items.iter().map(|s| json_string(s)).collect::<Vec<_>>().join(","))
}

pub fn dump() -> i32 {
    let Some((mut sess, mut pool, plan)) = load::read_path("/app/spoolbay/shift.spool") else {
        return 1;
    };
    let frost = prep(&sess, &pool);
    load::step(&mut sess, &mut pool, &plan);

    let frost_ids = frost.ids.borrow().clone();
    let live_ids = sess.ids.borrow().clone();
    let Some(frost_bag) = values(&frost_ids, &frost.cells) else { return 1; };
    let Some(live_bag) = values(&live_ids, &pool.cells) else { return 1; };
    if sess.flag && frost_bag == live_bag {
        return 1;
    }

    let body = format!(
        "{{\"tick\":{},\"mark\":{},\"frost_bag\":{},\"live_bag\":{}}}\n",
        sess.n0,
        sess.n1,
        pack(&frost_bag),
        pack(&live_bag)
    );
    let dest = Path::new("/app/inkpit/pair.json");
    if let Some(parent) = dest.parent() {
        if fs::create_dir_all(parent).is_err() { return 2; }
    }
    match fs::write(dest, body) {
        Ok(()) => 0,
        Err(_) => 2,
    }
}
